private async loadTestCases(input) {
  if (input.excelPath)                          return this.loadFromExcel(input.excelPath); // offline source checked first — an xlsx export needs no ADO connection at all
  if (input.tcIds    && input.tcIds.length)     return this.loadTcsByIds(input.tcIds); // .length guard: an empty array falls through to the next source
  if (input.storyIds && input.storyIds.length)  return this.loadByStoryIds(input.storyIds);
  if (input.featureId)                          return this.loadByFeature(input.featureId);
  throw new Error('Provide one of: --feature-id, --story-ids, --tc-ids, --excel'); // no source at all is a hard error, not a silent empty run
}

function parseStepsXml(stepsXml) {
  if (!stepsXml) return []; // test cases can have no steps (shared-steps refs, empty shells) — return empty, don't crash
  const steps = [];
  const stepMatches = stepsXml.matchAll(/<step[^>]*>([\s\S]*?)<\/step>/gi);
  let idx = 1;
  for (const m of stepMatches) {
    const inner = m[1]; // m[1] = the captured content between <step>...</step>
    const actionMatch = inner.match(/<action[^>]*>([\s\S]*?)<\/action>/i);
    const expectMatch = inner.match(/<expectedResult[^>]*>([\s\S]*?)<\/expectedResult>/i);
    const action = stripHtml(actionMatch?.[1] || '').trim(); // strip the HTML ADO wraps around rich-text, then trim; ?. so a missing <action> => empty string
    const expected = stripHtml(expectMatch?.[1] || '').trim();
    if (action) steps.push({ stepNumber: idx++, action, expected }); // only number steps that have an action; idx increments per KEPT step, so numbering is gap-free
  }
  return steps;
}

private groupByStory(testCases) {
  const map = new Map();
  for (const tc of testCases) {
    const key = tc.storyId ? String(tc.storyId) : 'ungrouped'; // stringify so numeric & string story IDs collide into one Map bucket; orphans -> 'ungrouped'
    const label = tc.storyTitle || (tc.storyId ? `Story ${tc.storyId}` : 'General'); // human label: real title, else 'Story <id>', else 'General' for the orphan bucket
    if (!map.has(key)) map.set(key, { groupTitle: label, groupId: tc.storyId, testCases: [] }); // create the bucket on first sight of a key; later tests with the same key just append
    map.get(key).testCases.push(tc);
  }
  return Array.from(map.values());
}

private async generateSpec(group) {
  const tcSummary = group.testCases.map(tc => {
    const stepText = tc.steps.map(s =>
      `  ${s.stepNumber}. ${s.action} → Expected: ${s.expected}`).join('\n');
    return `Test Case [TC-${tc.id}] P${tc.priority}: "${tc.title}"\n${stepText}`;
  }).join('\n\n');

  const prompt = `You are a senior business analyst. Reverse-engineer
the following QA test cases into a clear feature specification.

Feature/Story: "${group.groupTitle}"
--- TEST CASES ---
${tcSummary}
--- END ---

Based ONLY on what the test cases evidence, return valid JSON:
{ "featureDescription": "...", "acceptanceCriteria": [...],
  "inScope": [...], "outOfScope": [...] }`;

  const llmRes = await callGeminiFlash(prompt); // one LLM call per story group, so each section is reasoned about in isolation
  const parsed = JSON.parse(llmRes.answer.match(/\{[\s\S]*\}/)[0]); // greedy {...} slice pulls the JSON out of any surrounding prose or markdown fence before parsing
  return { groupTitle: group.groupTitle, groupId: group.groupId,
    tcCount: group.testCases.length, ...parsed, // spread the model fields in, but keep our own group metadata authoritative
    testCaseTitles: group.testCases.map(tc => `[TC-${tc.id}] ${tc.title}`) };
}

private async saveOutputs(result, ts, input) {
  const dir = input.outputDir || this.outputDir;
  const label = (result.featureTitle || 'tc-spec').replace(/[^a-zA-Z0-9]/g, '-').slice(0, 40); // sanitize the title into a safe filename slug: non-alphanumerics -> '-', capped at 40 chars

  const jsonPath = path.join(dir, `TcSpec_${label}_${ts}.json`);
  fs.writeFileSync(jsonPath, JSON.stringify(result, null, 2)); // full result pretty-printed — the canonical machine artifact

  const mdPath = path.join(dir, `TcSpec_${label}_${ts}.md`);
  fs.writeFileSync(mdPath, this.buildMarkdown(result));

  let docxPath;
  if (input.word) docxPath = await this.buildWord(result, dir, label, ts); // docx is opt-in; docxPath stays undefined otherwise, and the return reflects that

  return { json: jsonPath, md: mdPath, docx: docxPath };
}
